public class Solution {
    // SPEC: return the sum of elements at EVEN indexes (0, 2, 4, ...)
    public static int sumEvenIndexes(int[] arr) {
        int sum = 0;
        for (int i = 1; i < arr.length; i += 2) {
            sum += arr[i];
        }
        return sum;
    }
}

